#include <algorithm>
#include <array>
#include <cstdint>
#include <functional>
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace std;using R=vector<unsigned>;using Z=unsigned long long;
void need(bool b,const char*s){if(!b)throw runtime_error(s);}int bit(unsigned x){return __builtin_ctz(x);}Z power(Z b,int e){Z x=1;while(e--)x*=b;return x;}
R build(int i,int k,int j,int m){need((i==0||i==1)&&(k==0||k==1)&&j>=0&&m>=0,"parameters");vector<int>w{1};for(int t=0;t<i;t++)w.push_back(0);w.push_back(1);for(int t=0;t<j;t++)w.push_back(0);w.push_back(2);for(int t=0;t<k;t++)w.push_back(0);w.push_back(2);int q=w.size(),n=3+q+m;R r(n);r[0]=(1<<1)|(1<<2);r[2]=1<<1;for(int v=0;v<q;v++){int x=v+3;for(int a=0;a<3;a++){bool out=a<2&&(w[v]>>a&1);if(out)r[a]|=1<<x;else r[x]|=1<<a;}for(int u=v+1;u<q;u++)r[x]|=1<<(u+3);for(int c=3+q;c<n;c++)r[x]|=1<<c;}for(int c=3+q;c<n;c++){r[c]|=7;for(int d=c+1;d<n;d++)r[c]|=1<<d;}return r;}
Z count(R const&r){int n=r.size(),N=1<<n;vector<Z>d(size_t(N)*n);for(int u=0;u<n;u++)d[size_t(1<<u)*n+u]=1;for(int mask=1;mask<N;mask++)for(int u=0;u<n;u++)if(d[size_t(mask)*n+u]){unsigned z=r[u]&~mask;while(z){unsigned b=z&-z;z-=b;d[size_t(mask|b)*n+bit(b)]+=d[size_t(mask)*n+u];}}Z h=0;for(int u=0;u<n;u++)h+=d[size_t(N-1)*n+u];return h;}
Z literal(R const&r){int n=r.size();unsigned full=(1<<n)-1;Z h=0;function<void(int,unsigned)>go=[&](int u,unsigned used){if(used==full){h++;return;}unsigned z=r[u]&~used;while(z){unsigned b=z&-z;z-=b;go(bit(b),used|b);}};for(int u=0;u<n;u++)go(u,1<<u);return h;}
int crossrank(R const&r,int root){int n=r.size();vector<int>mate(n,-1);function<bool(int,unsigned&)>aug=[&](int u,unsigned&seen){for(int v=0;v<n;v++)if(v!=root&&(r[v]>>root&1)&&(r[u]>>v&1)&&!(seen>>v&1)){seen|=1<<v;if(mate[v]<0||aug(mate[v],seen)){mate[v]=u;return true;}}return false;};int ans=0;for(int u=0;u<n;u++)if(r[root]>>u&1){unsigned seen=0;ans+=aug(u,seen);}return ans;}
bool prime(Z n){if(n<2)return false;for(Z p=2;p<=n/p;p++)if(n%p==0)return false;return true;}
void rows(R const&r){cout<<'[';for(int v=0;v<(int)r.size();v++){if(v)cout<<',';cout<<r[v];}cout<<']';}
int main(){int grid=0;vector<array<Z,7>>records;for(int i=0;i<=1;i++)for(int k=0;k<=1;k++)for(int j=0;j<=2;j++)for(int m=0;m<=3;m++){auto r=build(i,k,j,m);Z B=4*(3+2*i)*(5+8*k),expected=B*power(2,j)*power(3,m);if(j)expected++;else expected--;Z h=count(r);need(h==expected&&literal(r)==expected,"literal tensor grid");if(m==1)need(crossrank(r,r.size()-1)==2,"ternary source crossing rank");if(j==1)need(crossrank(r,5+i)==1,"binary middle crossing rank");records.push_back({(Z)i,(Z)k,(Z)j,(Z)m,(Z)r.size(),B,h});grid++;}cout<<"{\"status\":\"PASS\",\"tensor_grid_graphs\":"<<grid<<",\"grid\":[";bool first=true;for(auto v:records){if(!first)cout<<',';first=false;cout<<'[';for(int z=0;z<7;z++){if(z)cout<<',';cout<<v[z];}cout<<']';}cout<<"],\"witnesses\":[";first=true;for(auto p:vector<array<int,5>>{{1,0,1,1,601},{0,1,1,1,937},{0,0,2,1,721},{0,0,1,3,3241}}){auto r=build(p[0],p[1],p[2],p[3]);Z h=count(r);need(h==(Z)p[4]&&literal(r)==h,"literal atom witness");bool isprime=prime(h);Z factor=isprime?h:h/7;need(isprime||(h%7==0&&prime(factor)),"prime or7p certificate");if(!first)cout<<',';first=false;cout<<"{\"parameters\":["<<p[0]<<','<<p[1]<<','<<p[2]<<','<<p[3]<<"],\"H\":"<<h<<",\"prime\":"<<(isprime?"true":"false")<<",\"prime_factor\":"<<factor<<",\"rows\":";rows(r);cout<<'}';}cout<<"]}\n";}
